(window.__APPSRC=window.__APPSRC||{})["xmvkq4zed--zw-sj-prepa-ped-j5-idesfm"]="{\n \"app\": \"xmvkq4zed\",\n \"id\": \"zw-sj-prepa-ped-j5-idesfm\",\n \"titre\": \"Préparation D.E (J) · J5 Pédiatrie IDE/SFM\",\n \"session\": \"J\",\n \"annee\": 2026,\n \"nq\": 55,\n \"nsuj\": 1,\n \"origines\": [\n  {\n   \"fichier\": \"prepa-de-2026/J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n   \"sha256\": \"5807cbdd1ccce6ba847839fc06174ea75b78716fe6a72829e5038a26f12629e3\"\n  }\n ],\n \"antennes\": [\n  {\n   \"name\": \"J DE PRÉPARATION AU D.E\",\n   \"slug\": \"j-preparation-de\",\n   \"session\": \"J\",\n   \"annee\": 2026,\n   \"existe\": true,\n   \"sujets\": [\n    {\n     \"name\": \"J Pédiatrie · Prépa D.E J5 (IDE/SFM)\",\n     \"slug\": \"prepa-ped-j5-idesfm\",\n     \"pages\": \"\",\n     \"count\": 55,\n     \"session\": \"J\",\n     \"annee\": 2026,\n     \"matiere\": \"Pédiatrie\",\n     \"source\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n     \"questions\": [\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__0\",\n       \"num\": \"1\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La section immédiate du cordon ombilical du nouveau-né après la sortie de la filière génitale expose celui-ci à une anémie ferriprive\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours demande de ligaturer et sectionner le cordon entre 1 et 3 minutes de vie, pas immédiatement. Le clampage retardé (2 à 3 min) optimise la transfusion placentaire vers l'enfant et permet d'éviter l'anémie (et l'hypoglycémie) ; une section immédiate prive le nouveau-né de ce sang, d'où le risque d'anémie par manque de fer.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Soins essentiels aux nouveau-nés (1-60 minutes de vie) ; Module de Néonatologie, ch. IV Accueil du nouveau-né – Clampage du cordon ; ch. VIII Prématurité – Anémie du prématuré\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__1\",\n       \"num\": \"2\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"JR a 15 minutes de vie. Né à terme. Son poids de naissance est de 3000 grammes. Dans le cadre des soins essentiels du nouveau-né, pour lutter contre la maladie hémorragique, je lui administre par voie orale 9 gouttes de vitamine K1.\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La posologie orale de la vitamine K1 est de 3 gouttes/kg de poids : 3 kg × 3 = 9 gouttes. La dose est donc juste et la voie orale est prévue par le cours (1 mg en IM si poids ≥ 2500 g, ou 3 gouttes/kg per os). Remarque : Dans le déroulement des soins essentiels, la vitamine K1 est donnée entre 60 et 90 minutes de vie, pas à 15 minutes (voir aussi la question 24). D'autres cours du projet donnent d'autres doses (2 mg per os dans le module de Néonatologie ; 5 mg IM dans L'essentiel en pédiatrie tropicale).\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Soins essentiels aux nouveau-nés – 60-90 minutes de vie\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__2\",\n       \"num\": \"3\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le collyre antiseptique administré au nouveau-né en salle de naissance a pour objectif de traiter une infection active de l'œil du nouveau-né\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le collyre (ou la pommade) est instillé systématiquement à tous les nouveau-nés, une seule fois, pour PRÉVENIR l'infection oculaire (conjonctivite à gonocoque) contractée lors du passage dans la filière génitale. Ce n'est pas un traitement d'une infection déjà présente.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Examen du nouveau-né – Besoin d'éviter le danger ; Module de Néonatologie, ch. IV – Les autres soins à faire au nouveau-né\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__3\",\n       \"num\": \"4\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Il existe trois types de toilette\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Ce sont les BAINS qui sont de trois types (bain de propreté, bain de détente, bain thérapeutique). La toilette est un seul soin de propreté, destiné au nouveau-né dont le cordon n'est pas tombé ou dont la plaie n'est pas cicatrisée. Remarque : Le cours précise que la toilette peut se faire à trois endroits (berceau, paillasse, incubateur) : ce sont des lieux, pas des types de toilette.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Toilette du nouveau-né – Définition ; Bain de l'enfant – Définition\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__4\",\n       \"num\": \"5\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Avant la toilette, il faut appliquer du lait de toilette sur tout le corps du nouveau-né\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Dans le déroulement de la toilette, on lave, on sèche l'enfant, puis on applique le beurre de karité (ou le lait corporel) sur le corps APRÈS la toilette, avant de l'habiller. Rien n'est appliqué avant la toilette.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Toilette du nouveau-né – Déroulement de la toilette\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__5\",\n       \"num\": \"6\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lorsque la température corporelle de l'enfant dépasse 39 degrés Celsius, il faut lui donner un bain tiède\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours précise que le bain (thérapeutique) en cas de fièvre n'est plus recommandé comme moyen physique pour traiter la fièvre chez l'enfant. Le bain thérapeutique est réservé aux dermatoses (voir question 30). Remarque : L'essentiel en pédiatrie tropicale (Fièvre de l'enfant – Rôles curatifs, moyens physiques) cite encore « proposer un bain d'eau tiède » parmi les moyens physiques ; la correction suit le cours de Santé infantile.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Bain de l'enfant – Définition (NB)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__6\",\n       \"num\": \"7\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les soins ombilicaux, la solution ou le gel de Chlorhexidine s'applique sur le cordon frais de la pointe du moignon à la base du cordon\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Sur le cordon frais (3 premiers jours), la chlorhexidine gel s'applique d'abord à la pointe du cordon, puis sur le moignon, puis à la base, en s'assurant que tout le cordon est bien imprégné. Le sens inverse (base → pointe) est réservé au cordon sec.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Soins ombilicaux – Déroulement du soin\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__7\",\n       \"num\": \"8\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le pansement à la Chlorhexidine se fait une fois par jour jusqu'à la cicatrisation\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La chlorhexidine gel s'applique une fois par jour, et on continue même après la chute du cordon ; les soins ombilicaux se poursuivent jusqu'à la cicatrisation de la plaie ombilicale.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Soins ombilicaux – Définition et Déroulement du soin\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__8\",\n       \"num\": \"9\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La fonction principale de l'incubateur est d'assurer la respiration d'un air filtré et humidifié\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Parmi les fonctions principales de l'incubateur, le cours cite : maintenir une température normale et stable, ASSURER LA RESPIRATION D'UN AIR FILTRÉ ET HUMIDIFIÉ, assurer un isolement infectieux et permettre la surveillance clinique.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Incubateur néonatal – Fonctions principales de l'incubateur\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__9\",\n       \"num\": \"10\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le transport médicalisé est une des indications de l'incubateur\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les indications de l'incubateur sont : le nouveau-né de petit poids de naissance, l'hypothermie et le transport médicalisé (il existe des incubateurs de transport).\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Incubateur néonatal – Indications de l'incubateur\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__10\",\n       \"num\": \"11\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans le carnet de santé mère-enfant, la partie réservée à l'accouchement concerne la 3ème partie\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le carnet de santé mère-enfant comprend 4 parties : 1) identité et conditions de vie des parents ; 2) suivi de la grossesse ; 3) L'ACCOUCHEMENT ; 4) suivi de l'enfant.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Carnet de santé mère-enfant – Introduction\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__11\",\n       \"num\": \"12\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Une absence de sourire social ou sourire-réponse à 3 mois ne doit pas faire objet de visite clé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le carnet prévoit des examens de l'enfant à des âges clés (3, 6, 9, 12, 24 mois). Le sourire-réponse fait partie des acquisitions attendues dans les premiers mois : son absence à 3 mois est un signe d'alerte du développement psychomoteur qui doit justement être recherché et noté lors de la visite clé de 3 mois (et faire envisager une référence).\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Carnet de santé mère-enfant – Suivi de l'enfant (examen de l'enfant à 3 mois) ; L'essentiel en pédiatrie tropicale (Dr Asse), Annexes – Principales étapes du développement psychomoteur ; complément hors cours du projet pour la notion de signe d'alerte\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__12\",\n       \"num\": \"13\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le respect de la confidentialité fait partie des principes de remplissage du carnet mère-enfant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le carnet est un document médico-légal, sous le sceau du secret médical. Le cours conclut que son remplissage doit observer les principes de confidentialité et de soins.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Carnet de santé mère-enfant – Intérêt et Conclusion\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__13\",\n       \"num\": \"14\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'enfant né à terme et correctement nourri triple son poids de naissance à 24 mois\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le poids de naissance est doublé à 3 mois (5 mois au lait artificiel), TRIPLÉ À 12 MOIS et multiplié par 4 à 2 ans (24 mois). À 24 mois il n'est donc pas « triplé ».\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Mensurations – Repères de gain de poids et tableau récapitulatif\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__14\",\n       \"num\": \"15\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La croissance des os, la taille et le périmètre crânien sont les éléments qualitatifs de la croissance de l'enfant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le cours définit la croissance QUANTITATIVE comme l'augmentation en poids, en taille et en volume des tissus et organes. La taille, le périmètre crânien (et la croissance des os) sont des indicateurs mesurables, donc quantitatifs, et non qualitatifs.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Mensurations – Définition\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__15\",\n       \"num\": \"16\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le colostrum qui est de couleur jaunâtre ou d'apparence claire et de consistance épaisse, constitue un excellent laxatif pour le bébé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le colostrum est le lait des premiers jours : jaune-orangé ou d'apparence claire, épais, riche en anticorps. Le cours précise que c'est un excellent laxatif : il aide l'évacuation du méconium.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Allaitement – Caractéristiques du colostrum ; L'essentiel en pédiatrie tropicale (Dr Asse), Nourrisson et enfant – Allaitement maternel\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__16\",\n       \"num\": \"17\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans les soins mère kangourou, la durée minimale du portage de l'enfant en discontinu recommandée est de 60 minutes\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Les SMK intermittents se pratiquent seulement à certains moments de la journée. Pour être bénéfiques (chaleur, stabilité, allaitement), les séances de portage ne doivent pas être trop courtes : la correction retient une durée minimale de 60 minutes par séance, car les changements fréquents de position stressent le bébé.\\n\\nSource : Module de Néonatologie, ch. XVII Méthode des soins mère kangourou – SMK intermittents ; durée minimale : explication hors cours du projet\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__17\",\n       \"num\": \"18\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La vérification et la mesure du résidu gastrique sont importantes avant le gavage chez l'enfant dont la sonde est déjà en place\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Avant chaque gavage, on vérifie que la sonde est bien en place puis on aspire et mesure le résidu gastrique : son volume et son aspect décident de la conduite (donner la ration, la réduire, sauter le repas, signaler). La surveillance du résidu gastrique figure dans les rôles de l'agent de santé chez le prématuré et l'hypotrophe.\\n\\nSource : Module de Néonatologie, ch. XVI Alimentation du nouveau-né – Alimentation par sonde nasogastrique ; L'essentiel en pédiatrie tropicale (Dr Asse), Nouveau-né prématuré – Rôles curatifs ; interprétation du résidu : complément hors cours du projet\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__18\",\n       \"num\": \"19\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le résidu gastrique supérieur au 1/3 de la ration administrée et propre signifie que la ration est trop importante pour l'enfant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Faux\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Un résidu PROPRE supérieur au tiers de la ration traduit surtout une vidange gastrique lente (intolérance digestive) : on le réinjecte, on adapte (réduit ou saute) le repas et on signale au médecin, car il peut annoncer une complication digestive. Ce n'est pas simplement « une ration trop importante ».\\n\\nSource : (explication hors cours du projet) – le module de Néonatologie cite les résidus abondants parmi les signes d'entérocolite (ch. VIII)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__19\",\n       \"num\": \"20\",\n       \"type\": \"QCD\",\n       \"typeLabel\": \"QCD\",\n       \"partieTitle\": \"Vrai ou faux\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Résidu gastrique absent signifie que la quantité de la ration précédente administrée est insuffisante\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Vrai\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Faux\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Vrai\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Un résidu absent signifie que tout le repas précédent a été vidé de l'estomac : l'enfant digère bien et la quantité donnée était insuffisante pour lui ; on peut augmenter progressivement la ration selon la tolérance.\\n\\nSource : (explication hors cours du projet)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__20\",\n       \"num\": \"21\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les soins essentiels du nouveau-né sont limités aux\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"5 premières minutes de vie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"60 premières minutes de vie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"90 premières minutes de vie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 90 premières minutes de vie\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le cours précise que, dans son cadre, les soins essentiels du nouveau-né sont limités aux 90 premières minutes de vie (0-1 min, 1-60 min, 60-90 min).\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Soins essentiels aux nouveau-nés – Définition\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__21\",\n       \"num\": \"22\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la première heure de vie, il est nécessaire de mesurer la température du nouveau-né toutes les\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"10 minutes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"15 minutes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"20 minutes\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. 15 minutes\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Entre 1 et 60 minutes de vie, on mesure la température du nouveau-né toutes les 15 minutes, soit 4 fois dans l'heure.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Soins essentiels aux nouveau-nés – 1-60 minutes de vie\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__22\",\n       \"num\": \"23\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"La mise du nouveau-né au sein doit se faire précocement entre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"0 et 15 minutes de vie\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"15 et 30 minutes de vie\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"30 et 60 minutes de vie\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 30 et 60 minutes de vie\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Dans le déroulement des soins essentiels, l'agent de santé aide la mère à mettre le nouveau-né au sein entre 30 et 60 minutes de vie. Remarque : Le chapitre Allaitement du même cours indique « 15 à 30 mn après l'accouchement » et l'IHAB « dans la demi-heure » ; la correction suit le déroulement des soins essentiels.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Soins essentiels aux nouveau-nés – 1-60 minutes de vie\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__23\",\n       \"num\": \"24\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"GG est né à 14H30 minute à terme. Il est en bonne santé apparente. Je mesure son poids et lui administre la vitamine K1 en IM entre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"14h30 min et 14h45 min\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"14h 46 min et 15h00 min\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"15h31 min et 16h00 min\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 15h31 min et 16h00 min\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"La mesure du poids et l'administration de la vitamine K1 se font dans la phase 60-90 minutes de vie. Né à 14 h 30, GG doit donc les recevoir entre 15 h 30 et 16 h 00.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Soins essentiels aux nouveau-nés – 60-90 minutes de vie\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__24\",\n       \"num\": \"25\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nouveau-né Teha est en bonne santé et nourri au sein. Il présente un écoulement blanchâtre au niveau de la vulve. Cet écoulement est appelé\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Leucorrhée blanchâtre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Crise génitale\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Colostrum\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Crise génitale\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Chez la petite fille, un écoulement de pertes blanches (ou de sang) par la vulve est une crise génitale : passagère, due aux hormones maternelles, elle ne doit pas inquiéter. Ce n'est ni une leucorrhée pathologique ni du colostrum.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Examen du nouveau-né – Organes génitaux externes ; Module de Néonatologie, ch. IV – Appareil génital\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__25\",\n       \"num\": \"26\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le nouveau-né normal a un âge gestationnel compris entre\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"37 et 41 semaines + 6 jours\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"7 et 42 semaines + 6 jours\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"38 et 42 semaines + 6 jours\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. 37 et 41 semaines + 6 jours\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le nouveau-né normal (à terme) a un âge gestationnel compris entre 37 et 41 semaines + 6 jours d'aménorrhée ; avant 37 SA il est prématuré, à partir de 42 SA il est post-terme.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Le nouveau-né – Nouveau-né normal, Définition\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__26\",\n       \"num\": \"27\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Relevez la lettre correspondant aux différentes étapes de l'examen du nouveau-né\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Cotation d'APGAR, appréciation de la respiration du nouveau-né, mensurations, examen somatique par appareil\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Cotation d'APGAR, appréciation du nouveau-né dans son ensemble, mensurations, examen somatique par appareil\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Cotation des réflexes, appréciation du nouveau-né dans son ensemble, mensurations, examen somatique par appareil\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Cotation d'APGAR, appréciation du nouveau-né dans son ensemble, mensurations, examen somatique par appareil\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Les étapes de l'examen du nouveau-né sont : la cotation d'APGAR, l'appréciation du nouveau-né dans son ensemble, les mensurations, l'examen somatique par appareil.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Examen du nouveau-né en salle de naissance – Examen physique\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__27\",\n       \"num\": \"28\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mienmo vient de naître il y a 1 mn. Elle présente une cyanose des extrémités, une fréquence cardiaque à 120 batt/mn, un cri vigoureux, une attitude de WM, respiration irrégulière. Le score d'APGAR de Mienmo est égal à\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"5\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"7\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"8\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 8\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Cotation : cyanose des extrémités (corps rose) = 1 ; FC 120/min (> 100) = 2 ; cri vigoureux = 2 ; attitude en WM (bon tonus en flexion) = 2 ; respiration irrégulière = 1. Total = 8.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Examen du nouveau-né – Tableau d'APGAR\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__28\",\n       \"num\": \"29\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi le matériel de toilette cité ci-dessous, il y a un intrus : lequel ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Une paire de moufles\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Une brosse à dent\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Du beurre de karité\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Une brosse à dent\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La liste du matériel de toilette comprend une paire de moufles, du beurre de karité (ou lait corporel), une brosse à CHEVEUX… mais pas de brosse à dent : c'est l'intrus.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Toilette du nouveau-né – Matériel de soins\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__29\",\n       \"num\": \"30\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le bain thérapeutique est recommandé en cas de\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Fièvre\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Dermatoses\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Convulsions\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Dermatoses\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le bain thérapeutique est réalisé en cas de dermatose. Il n'est plus recommandé en cas de fièvre, et n'a pas d'indication dans les convulsions.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Bain de l'enfant – Définition\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__30\",\n       \"num\": \"31\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Mme DKT envoie au centre de santé son nouveau-né présentant un muguet buccal. L'agent de santé décide de faire le soin de la bouche avec\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Du sérum glucosé isotonique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Du sérum bicarbonaté à 14 ‰\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Du sérum glucosé à 10 %\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"De l'éosine aqueuse à 2 %\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Du sérum glucosé à 10 %\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Le muguet est une mycose buccale (candidose). Pour le soin de la bouche, le cours prévoit une compresse imbibée de SÉRUM BICARBONATÉ À 14 ‰ ; le muguet se traite ensuite par un antimycosique (gel après chaque tétée, Nystatine dans la PCIMNE).\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Soins des orifices – Matériel et technique des soins de la bouche ; Allaitement – Difficultés liées à l'enfant (muguet) ; Livret de tableaux PCIMNE – Suivi du muguet\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__31\",\n       \"num\": \"32\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Vous recevez à votre permanence le nouveau-né Tahi au 5ème jour de vie, avec une pâte de médicament traditionnel sur le cordon ombilical. Vous décidez d'effectuer les soins ombilicaux en commençant\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"De la base vers la pointe du moignon du cordon ombilical\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"De la pointe du moignon du cordon vers la base de l'ombilic\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"De la base vers la moitié du moignon du cordon\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. De la base vers la pointe du moignon du cordon ombilical\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Au 5e jour, le cordon est sec (pansement du cordon sec à partir du 4e jour). Le cours précise : lorsque le cordon est sec, l'application de la chlorhexidine commence à la BASE du cordon, puis vers la pointe. On déconseille aussi les produits traditionnels sur le cordon.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Soins ombilicaux – Définition (3 phases) et Déroulement du soin (NB)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__32\",\n       \"num\": \"33\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les dispositions suivantes, deux sont à observer par l'agent de santé avant les soins ombilicaux. Lesquelles ? (plusieurs réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Ôter les bijoux\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Habiller le nouveau-né\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Porter un cache-nez\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Remercier la mère\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Noter le soin dans le carnet ou le dossier médical du nouveau-né\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Ôter les bijoux ; C. Porter un cache-nez\",\n       \"answerLetters\": [\n        \"A\",\n        \"C\"\n       ],\n       \"explanation\": \"Dans les dispositions de l'agent de santé avant le soin : ôter les bijoux (montre, bague, bracelet…) et porter un cache-nez, avec blouse propre, ongles courts, lavage des mains. Habiller l'enfant, remercier la mère et noter le soin se font APRÈS le soin.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Soins ombilicaux – Disposition de l'agent de santé ; Après le soin\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__33\",\n       \"num\": \"34\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'antiseptique recommandé pour les soins ombilicaux est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'Hexomidine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"L'Éosine aqueuse\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La Chlorhexidine gel\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. La Chlorhexidine gel\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"En Côte d'Ivoire, l'antiseptique retenu pour le pansement ombilical est la chlorhexidine (gel).\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Soins ombilicaux – Définition\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__34\",\n       \"num\": \"35\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour affirmer qu'une gestante est bien suivie, il faut qu'elle réalise\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Au plus 3 consultations prénatales\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Au moins 4 consultations prénatales\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Au plus 2 consultations prénatales\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Au moins 4 consultations prénatales\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le carnet (CCC page 6) demande à la future maman de se rendre en consultation prénatale au moins quatre (4) fois ; l'agent de santé conseille un minimum de 4 CPN. Remarque : Le même cours rappelle que la législation ivoirienne prévoit 8 CPN ; le seuil de « bien suivie » retenu ici est le minimum de 4.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Carnet de santé mère-enfant – Page 6 ; L'essentiel en pédiatrie tropicale (Dr Asse), Nouveau-né normal – Rôles avant la naissance\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__35\",\n       \"num\": \"36\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Lorsque survient un granulome ombilical (bourgeon) après la chute du cordon, le geste approprié consiste à\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Continuer l'application de la chlorhexidine\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Traiter avec du crayon au Nitrate d'argent\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Appliquer de l'alcool à 90°\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Traiter avec du crayon au Nitrate d'argent\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le granulome ombilical (plaie bourgeonnante) est un incident des soins du cordon ; son traitement est le crayon de nitrate d'argent (à prévoir dans le matériel si la plaie bourgeonne).\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Soins ombilicaux – Matériel ; Problèmes de santé associés (incidents)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__36\",\n       \"num\": \"37\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les éléments de surveillance du nouveau-né dans l'incubateur sont\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Température ; Coloration ; poids ; Rythme cardiaque\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Température ; Coloration ; Respiration ; Rythme cardiaque\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Température ; périmètre brachial ; Respiration ; Rythme cardiaque\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Température ; Coloration ; Respiration ; Rythme cardiaque\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Chez l'enfant en incubateur, on surveille : la température, la coloration, la respiration et le rythme cardiaque.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Incubateur néonatal – Éléments de surveillance chez l'enfant\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__37\",\n       \"num\": \"38\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les signes suivants, relever les deux signes d'une prise de sein correcte (plusieurs réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La bouche de l'enfant à moitié ouverte\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La joue de l'enfant touche le sein de sa mère\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Les lèvres du nourrisson sont en éversion\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"L'enfant suce les deux tiers du mamelon\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'aréole de la mère est peu visible au-dessus du mamelon\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. Les lèvres du nourrisson sont en éversion ; E. L'aréole de la mère est peu visible au-dessus du mamelon\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Signes d'une bonne prise de sein : bouche grande ouverte qui couvre l'aréole, menton qui touche le sein, LÈVRES (inférieure) EN ÉVERSION, aréole peu visible (la bouche en prend une large partie). Une bouche à moitié ouverte ou le fait de ne sucer que le mamelon sont des signes de mauvaise prise.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Allaitement – Technique de la bonne prise du sein ; L'essentiel en pédiatrie tropicale (Dr Asse), Allaitement maternel – Aide à l'allaitement\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__38\",\n       \"num\": \"39\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la physiologie de la lactation, la prolactine réalise les deux actions suivantes (plusieurs réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Augmente le taux d'œstrogène\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Favorise la production du lait\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Provoque la contraction des cellules alvéolaires\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Réalise une action contraceptive chez la mère\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Propulse le lait dans les différents canaux lactifères\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Favorise la production du lait ; D. Réalise une action contraceptive chez la mère\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"La prolactine (antéhypophyse) stimule la production du lait et réalise une action contraceptive en faisant baisser les œstrogènes et la progestérone. C'est l'OCYTOCINE (post-hypophyse) qui contracte les cellules alvéolaires et propulse le lait dans les canaux.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Allaitement – Physiologie de la lactation (après l'accouchement)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__39\",\n       \"num\": \"40\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la physiologie de la lactation, la prolactine réalise les deux actions suivantes (plusieurs réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Augmente le taux d'œstrogène\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Favorise la production du lait\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Provoque la contraction des cellules alvéolaires\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Réalise une action contraceptive chez la mère\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Propulse le lait dans les différents canaux lactifères\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. Favorise la production du lait ; D. Réalise une action contraceptive chez la mère\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Même réponse que la question 39 : production du lait et action contraceptive pour la prolactine ; contraction des cellules alvéolaires et éjection du lait pour l'ocytocine. Remarque : Question en double dans le sujet (identique à la question 39).\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Allaitement – Physiologie de la lactation\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__40\",\n       \"num\": \"41\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'âge recommandé par l'OMS pour l'ablactation chez le nourrisson est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"6 mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"12 mois\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"18 mois\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"24 mois\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"D. 24 mois\",\n       \"answerLetters\": [\n        \"D\"\n       ],\n       \"explanation\": \"Les recommandations (OMS/UNICEF) : allaitement exclusif jusqu'à 6 mois, puis aliments de complément, et poursuite de l'allaitement jusqu'à 2 ans (24 mois) ou plus ; le sevrage complet (ablactation) se fait à 2 ans.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Allaitement – Recommandations générales ; L'essentiel en pédiatrie tropicale (Dr Asse), Allaitement maternel – Modalités recommandées\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__41\",\n       \"num\": \"42\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Un nourrisson de 4 mois est nourri au lait maternel et reçoit du PRIMALAN sirop depuis la naissance pour un problème d'allergie. La modalité d'alimentation de ce nourrisson est\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Allaitement exclusif\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Allaitement prépondérant\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Alimentation mixte\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Allaitement exclusif\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"L'allaitement exclusif consiste à nourrir l'enfant uniquement au lait maternel, sans eau, tisane, jus ni autre aliment, À L'EXCEPTION DES MÉDICAMENTS PRESCRITS. Le Primalan sirop étant un médicament prescrit, l'enfant reste en allaitement exclusif.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Allaitement – Définitions (allaitement exclusif)\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__42\",\n       \"num\": \"43\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Au nombre des directives établies par l'OMS pour l'alimentation du nourrisson et du jeune enfant dans le contexte du VIH, il y a\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La pratique et la durée de l'allaitement\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La mise au sein tardive\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Le choix systématique de l'alimentation de remplacement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. La pratique et la durée de l'allaitement\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"La Directive 2 de l'OMS pour l'ANJE dans le contexte du VIH porte sur la pratique et la durée de l'allaitement. La mise au sein doit au contraire être précoce, et l'alimentation de remplacement n'est choisie que si les conditions AFADS sont réunies (pas systématiquement).\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, ANJE dans le contexte du VIH/SIDA – Directives\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__43\",\n       \"num\": \"44\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les critères ci-dessous, relevez 2 critères qui justifient le choix de l'alimentation de remplacement (plusieurs réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Accessible\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Fiable\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Justiciable\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Discutable\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Durable\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"A. Accessible ; E. Durable\",\n       \"answerLetters\": [\n        \"A\",\n        \"E\"\n       ],\n       \"explanation\": \"Les conditions AFADS : Acceptable, Faisable, Abordable (le cours précise « Accessible »), Durable et Sûre. Parmi les propositions, seuls « Accessible » et « Durable » en font partie.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Alimentation de remplacement – Conditions AFADS\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__44\",\n       \"num\": \"45\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour préparer le bol de lait d'un nourrisson de 5 mois avec du lait infantile, indiquez la lettre correspondant à la bonne réponse\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"5 mesurettes rases de lait + 200 ml d'eau\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"6 mesurettes rases de lait + 210 ml d'eau\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"7 mesurettes rases de lait + 210 ml d'eau\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. 7 mesurettes rases de lait + 210 ml d'eau\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"À 5 mois, la ration est de 200 ml (210 ml dans le tableau récapitulatif) en 4 repas. Le lait maternisé se reconstitue à 1 mesurette rase pour 30 ml d'eau : 200/30 = 6,67 → 7 mesurettes, soit 7 × 30 = 210 ml d'eau.\\n\\nSource : Cours de Santé infantile L1 IDE-SFM, Alimentation de remplacement – Ration selon l'âge ; Reconstitution des laits maternisés\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__45\",\n       \"num\": \"46\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Les SMK comportent 3 composantes essentielles. Parmi les propositions suivantes, indiquez celle qui n'est pas une composante des SMK\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Soins thermiques\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Soins essentiels du nouveau-né\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Allaitement\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Soins essentiels du nouveau-né\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"La méthode kangourou associe le contact peau à peau permanent (qui assure les soins thermiques) et l'allaitement exclusif au sein, complétés par le suivi/sortie de l'enfant. Les soins essentiels du nouveau-né sont une stratégie distincte (90 premières minutes de vie), pas une composante des SMK.\\n\\nSource : Module de Néonatologie, ch. XVII Méthode des soins mère kangourou – Définition et objectifs ; 3e composante (suivi) : complément hors cours du projet\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__46\",\n       \"num\": \"47\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Domi est sous photothérapie, la surveillance de sa température se fait\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Toutes les 15 minutes\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Toutes les 30 minutes\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Toutes les 4 heures\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Toutes les 4 heures\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Sous photothérapie, la température fait partie de la surveillance car la photothérapie expose à l'hyperthermie (et à la déshydratation). La correction nationale retient une prise de température toutes les 4 heures. Remarque : Le rythme « toutes les 4 heures » n'est pas écrit dans le chapitre photothérapie ; le module de Néonatologie le donne pour la surveillance du nouveau-né alimenté (ch. XVI).\\n\\nSource : Module de Néonatologie, ch. X Ictère néonatal – Conduite de la photothérapie (surveillance, risques) ; L'essentiel en pédiatrie tropicale (Dr Asse), Ictère du nouveau-né – Précautions pour la photothérapie\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__47\",\n       \"num\": \"48\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Si la sonde est en place et que le résidu gastrique est supérieur au 1/3 de la ration et sale ; il faut trouver l'intrus dans les gestes à poser\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Faire un lavage gastrique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Sauter le repas\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Injecter 20 cc de Ringer lactate\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"C. Injecter 20 cc de Ringer lactate\",\n       \"answerLetters\": [\n        \"C\"\n       ],\n       \"explanation\": \"Un résidu supérieur au tiers et sale (bilieux, sanglant) fait suspecter un problème digestif : on aspire/lave l'estomac, on saute le repas et on alerte le médecin. Le Ringer lactate est un soluté de perfusion INTRAVEINEUSE (remplissage en cas de choc) : il ne s'injecte pas dans la sonde, c'est l'intrus.\\n\\nSource : Module de Néonatologie, ch. VIII Prématurité – Entérocolite ulcéro-nécrosante (arrêt de l'alimentation orale, sonde en drainage, Ringer lactate en perfusion) ; conduite pratique : complément hors cours du projet\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__48\",\n       \"num\": \"49\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Quelles sont les trois formes principales de malnutrition ?\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Sous-alimentation, carences alimentaires, suralimentation\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Obésité, diabète, hypertension\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Kwashiorkor, marasme, obésité\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Sous-alimentation, carences alimentaires, suralimentation\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Le cours distingue la malnutrition par défaut (sous-nutrition), la malnutrition par excès (suralimentation, obésité) et la malnutrition par déséquilibre (carences). Kwashiorkor et marasme sont deux formes de la sous-nutrition ; obésité, diabète et HTA ne sont pas des formes de malnutrition.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Nourrisson et enfant – Malnutrition de l'enfant, Définition et limite du thème\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__49\",\n       \"num\": \"50\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"L'enfant ayant le marasme présente les signes cliniques suivants\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Peau sèche, craquelée et dépigmentée\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Un visage creusé, vieillot avec un regard vif et intéressé\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Anorexie-diarrhée-triste\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. Un visage creusé, vieillot avec un regard vif et intéressé\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le marasme (carence globale chronique) donne un enfant très amaigri, au visage creusé « de vieillard » avec un regard vif, affamé et actif, sans œdème ni troubles de la pigmentation. Peau dépigmentée, anorexie et tristesse évoquent le kwashiorkor.\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Malnutrition de l'enfant – Formes cliniques : Marasme\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__50\",\n       \"num\": \"51\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Le diagnostic de certitude du paludisme repose sur\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"La clinique seulement\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La goutte épaisse ou le test de diagnostic rapide positif\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La numération formule sanguine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La coloration des conjonctives\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"B. La goutte épaisse ou le test de diagnostic rapide positif\",\n       \"answerLetters\": [\n        \"B\"\n       ],\n       \"explanation\": \"Le diagnostic biologique (de certitude) du paludisme repose sur la goutte épaisse et le frottis sanguin, et à défaut sur le test de diagnostic rapide. La clinique seule ne suffit pas (signes non spécifiques).\\n\\nSource : L'essentiel en pédiatrie tropicale (Dr Asse), Paludisme de l'enfant – Diagnostic positif, Examen para clinique\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__51\",\n       \"num\": \"52\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Pour rechercher les facteurs favorisant de la maladie chez l'enfant je m'appuie sur\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Le triangle pédiatrique\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"Le losange pédiatrique\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La pyramide pédiatrique\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": false,\n       \"answer\": \"A. Le triangle pédiatrique\",\n       \"answerLetters\": [\n        \"A\"\n       ],\n       \"explanation\": \"Pour rechercher les facteurs favorisants d'une maladie chez l'enfant, on s'appuie sur le triangle pédiatrique, qui relie l'enfant, sa famille (la mère) et son environnement : chaque côté peut contenir des facteurs favorisants (âge, état nutritionnel ; pratiques et niveau des parents ; hygiène, conditions de vie).\\n\\nSource : (explication hors cours du projet) – L'essentiel en pédiatrie tropicale classe d'ailleurs les facteurs favorisants « liés à l'enfant » et « liés à l'environnement »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__52\",\n       \"num\": \"53\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les propositions suivantes deux ne sont pas des principes de la PCIMNE. Lesquels ? (plusieurs réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"Destinée aux agents de santé des ESPC\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La gratuité\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"Approche syndromique\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"Approche systématique\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"L'efficacité\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"B. La gratuité ; D. Approche systématique\",\n       \"answerLetters\": [\n        \"B\",\n        \"D\"\n       ],\n       \"explanation\": \"Le cours liste comme principes : destinée aux agents de santé des ESPC, approche syndromique, approche systématique, utilisation de signes spécifiques pour classer, approche rationnelle du traitement, conseil à la mère, continuité des soins. La gratuité n'en fait pas partie.\\n\\nSource : Cours PCIMNE 2026 – Généralités sur la PCIMNE, diapositive « Principes »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null,\n       \"off\": true\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__53\",\n       \"num\": \"54\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Parmi les principaux symptômes, relever deux à rechercher chez l'enfant de 2 mois à 5 ans, dans la PCIMNE (plusieurs réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"L'incapacité de boire ou de téter\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"La convulsion\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"La difficulté respiratoire\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"La léthargie\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"Le problème d'oreille\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. La difficulté respiratoire ; E. Le problème d'oreille\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"Chez l'enfant de 2 mois à 5 ans, on recherche les 4 principaux symptômes : toux ou difficulté respiratoire, diarrhée, fièvre, PROBLÈME D'OREILLE. L'incapacité de boire ou téter, les convulsions et la léthargie sont des signes généraux de danger, pas des « principaux symptômes ».\\n\\nSource : Cours PCIMNE 2026 – Généralités sur la PCIMNE, diapositives « Signes généraux de danger » et « Évaluer l'enfant malade »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      },\n      {\n       \"id\": \"j-preparation-de__prepa-ped-j5-idesfm__54\",\n       \"num\": \"55\",\n       \"type\": \"QCM\",\n       \"typeLabel\": \"QCM\",\n       \"partieTitle\": \"Questions à choix multiple\",\n       \"caseTitle\": null,\n       \"caseData\": null,\n       \"text\": \"Dans la PCIMNE, deux de ces fiches utilisées correspondent à différentes tranches d'âge qui sont de (plusieurs réponses)\",\n       \"options\": [\n        {\n         \"letter\": \"A\",\n         \"text\": \"0 à 1 mois\"\n        },\n        {\n         \"letter\": \"B\",\n         \"text\": \"1 mois à 2 mois\"\n        },\n        {\n         \"letter\": \"C\",\n         \"text\": \"0 à 1 semaine\"\n        },\n        {\n         \"letter\": \"D\",\n         \"text\": \"1 mois à 6 mois\"\n        },\n        {\n         \"letter\": \"E\",\n         \"text\": \"2 mois à 5 ans\"\n        }\n       ],\n       \"mode\": \"mcq\",\n       \"multi\": true,\n       \"answer\": \"C. 0 à 1 semaine ; E. 2 mois à 5 ans\",\n       \"answerLetters\": [\n        \"C\",\n        \"E\"\n       ],\n       \"explanation\": \"La PCIMNE utilise trois fiches de prise en charge : nouveau-nés de 0 à 1 semaine, enfants de 1 semaine à 2 mois, enfants de 2 mois à 5 ans. Parmi les propositions, seules « 0 à 1 semaine » et « 2 mois à 5 ans » correspondent.\\n\\nSource : Cours PCIMNE 2026 – Généralités sur la PCIMNE, diapositive « Fiches de prise en charge »\",\n       \"sourceDoc\": \"Prépa D.E — J5 Pédiatrie IDE/SFM (corrigé expliqué)\",\n       \"sourceFile\": \"J5_Pediatrie_IDE-SFM_Corrige_explique.pdf\",\n       \"sourcePage\": null\n      }\n     ]\n    }\n   ]\n  }\n ]\n}";
